import 'package:flutter/material.dart';import 'package:myapp/utils/app_theme.dart';class ThemeProvider extends ChangeNotifier {  bool _isDarkMode = false;  bool get isDarkMode => _isDarkMode;  ThemeMode get themeMode => _isDarkMode ? ThemeMode.dark : ThemeMode.light;  ThemeData get themeData =>      _isDarkMode ? AppTheme.darkTheme : AppTheme.lightTheme;  void syncWithUser(bool? darkMode) {    _isDarkMode = darkMode ?? false;    notifyListeners();  }  Future<void> toggleTheme(Future<void> Function(bool) onPersist) async {    _isDarkMode = !_isDarkMode;    await onPersist(_isDarkMode);    notifyListeners();  }  Future<void> setTheme(      bool isDark, Future<void> Function(bool) onPersist) async {    if (_isDarkMode == isDark) return;    _isDarkMode = isDark;    await onPersist(_isDarkMode);    notifyListeners();  }}